import React, { useState } from 'react';
import styles from './InputField.module.css';
import Icon from '../Icon/Icon';
import { ICONS } from '../../../assets/icons/ICONS';

const InputField = ({ label, type = 'text', name, placeholder, value, onChange }) => {
  const [isPasswordVisible, setPasswordVisible] = useState(false);

  const isPasswordField = type === 'password';

  const togglePasswordVisibility = () => {
    setPasswordVisible(!isPasswordVisible);
  };

  // O tipo do input muda com base no estado
  const inputType = isPasswordVisible ? 'text' : 'password';

  return (
    <div className={styles.group}>
      <label htmlFor={name} className={styles.label}>{label}</label>
      <div className={styles.inputWrapper}>
        <input
          // Usa 'inputType' se for um campo de senha, caso contrário usa o tipo original
          type={isPasswordField ? inputType : type}
          id={name}
          name={name}
          placeholder={placeholder}
          className={styles.input}
          value={value}
          onChange={onChange}
        />
        {/* Mostra o botão de olho apenas se for um campo de senha */}
        {isPasswordField && (
          <button type="button" className={styles.toggleButton} onClick={togglePasswordVisibility}>
            <Icon path={isPasswordVisible ? ICONS.eyeOff : ICONS.eye} />
          </button>
        )}
      </div>
    </div>
  );
};

export default InputField;
